import json
from itertools import permutations

def solve_puzzle():
    houses = [1, 2, 3, 4]
    names = ["Peter", "Arnold", "Eric", "Alice"]
    pets = ["bird", "fish", "dog", "cat"]

    solutions = []

    for name_perm in permutations(names):
        pos_name = {name_perm[i]: i + 1 for i in range(4)}

        # Clue 2: Eric is not in the first house.
        if pos_name["Eric"] == 1:
            continue
        # Clue 5: Alice is not in the first house.
        if pos_name["Alice"] == 1:
            continue
        # From Clue 6 and 4 combined: Arnold (fish) is one house away from Peter (exactly one between)
        if abs(pos_name["Arnold"] - pos_name["Peter"]) != 2:
            continue

        for pet_perm in permutations(pets):
            pos_pet = {pet_perm[i]: i + 1 for i in range(4)}

            # Clue 3: Eric is the person who keeps a pet bird.
            if pos_name["Eric"] != pos_pet["bird"]:
                continue
            # Clue 6: Arnold is the person with an aquarium of fish.
            if pos_name["Arnold"] != pos_pet["fish"]:
                continue
            # Clue 4: One house between the person with fish and Peter.
            if abs(pos_pet["fish"] - pos_name["Peter"]) != 2:
                continue
            # Clue 1: The person who owns a dog is somewhere to the right of Alice.
            if not (pos_pet["dog"] > pos_name["Alice"]):
                continue

            # If all constraints pass, record the solution
            solutions.append((name_perm, pet_perm))

    if not solutions:
        raise ValueError("No solution found.")

    # Assuming unique solution; take the first
    name_perm, pet_perm = solutions[0]

    rows = []
    for i, house in enumerate(houses):
        rows.append([str(house), name_perm[i], pet_perm[i]])

    output = {
        "solution": {
            "header": ["House", "Name", "Pet"],
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
